let PLAYLIST_TRACKS = RADIO_DATA_BAKED.playlist || [];
let WEEK_TRACKS = RADIO_DATA_BAKED.week || [];
let RADIO_TRACKS = PLAYLIST_TRACKS.length ? PLAYLIST_TRACKS : WEEK_TRACKS;
let rStation = PLAYLIST_TRACKS.length ? 'playlist' : 'week';
let rDataReady = true;
let rIdx = -1, rPlaying = false, rErrCount = 0;
const raudio = document.getElementById('raudio');
const ledMain = document.getElementById('ledMain');
const ledSub = document.getElementById('ledSub');
const playBtn = document.getElementById('playBtn');
const stereo = document.getElementById('stereo');
const rprog = document.getElementById('rprog');
function ledScroll(txt) {
  if(!ledMain) return;
  ledMain.textContent = '';
  const s = document.createElement('span');
  s.className = 'led-scroll';
  s.textContent = txt + '  ★  ' + txt + '  ★  ';
  ledMain.appendChild(s);
}
function radioLoad(i) {
  if(!RADIO_TRACKS.length) return;
  rIdx = (i + RADIO_TRACKS.length) % RADIO_TRACKS.length;
  const t = RADIO_TRACKS[rIdx];
  raudio.src = t.stream;
  if(typeof markPlayingRow==='function') markPlayingRow(t.suno);
  ledScroll('♪ ' + t.title.toUpperCase());
  if(ledSub) ledSub.textContent = 'POSTED BY ' + (t.member||'TSCMS MEMBER').toUpperCase() + (t.artist ? ' · ' + t.artist.toUpperCase() : '');
}
function radioPlay() {
  if(!RADIO_TRACKS.length){ if(ledSub) ledSub.textContent='NO TRACKS AVAILABLE'; return; }
  if(window.TSCMSAudio)TSCMSAudio.requestPlay('radio');
  if(typeof clearDayPlaying==='function')clearDayPlaying();
  if(typeof syncDayButtons==='function')syncDayButtons();
  if(window.TSCMSClearStaticRow)window.TSCMSClearStaticRow();
  if(rIdx < 0 || !raudio.getAttribute('src')) radioLoad(rIdx < 0 ? 0 : rIdx);
  raudio.play().then(function(){
    rPlaying = true; rErrCount = 0;
    if(playBtn) playBtn.textContent = '▶ PLAY';
    if(stereo){ stereo.textContent = '● ON AIR'; stereo.classList.add('on'); stereo.classList.remove('paused'); }
  }).catch(function(){ if(ledSub) ledSub.textContent='TAP PLAY ONCE TO START THE MUSIC'; });
}
function radioPause() {
  raudio.pause(); rPlaying = false;
  if(stereo){ stereo.textContent='● PAUSED'; stereo.classList.remove('on'); stereo.classList.add('paused'); }
  if(playBtn) playBtn.textContent='▶ PLAY';
}
function radioStop() {
  raudio.pause(); raudio.removeAttribute('src'); raudio.load();
  rPlaying = false; rIdx = -1;
  if(stereo){ stereo.textContent='● STANDBY'; stereo.classList.remove('on','paused'); }
  if(playBtn) playBtn.textContent='▶ START';
  if(ledSub) ledSub.textContent='TAP START · SIT BACK · ENJOY THE SHOW';
}
function radioNext(){ if(RADIO_TRACKS.length){ radioLoad(rIdx+1); radioPlay(); } }
function radioPrev(){ if(RADIO_TRACKS.length){ radioLoad(rIdx-1); radioPlay(); } }
function radioStation(name){
  rStation = name;
  RADIO_TRACKS = name==='playlist' ? PLAYLIST_TRACKS : WEEK_TRACKS;
  document.getElementById('stPlaylist').classList.toggle('on', name==='playlist');
  document.getElementById('stWeek').classList.toggle('on', name==='week');
  if(rPlaying || rIdx >= 0){ radioLoad(0); if(rPlaying) radioPlay(); }
}
function radioVol(v){
  raudio.volume = v/100;
  const volEl = document.getElementById('vol');
  if(volEl) volEl.style.setProperty('--vp', v+'%');
}
if(raudio){
  raudio.addEventListener('timeupdate', function(){
    if(raudio.duration && rprog){
      rprog.style.width = (raudio.currentTime/raudio.duration*100)+'%';
    }
  });
  raudio.addEventListener('ended', function(){ radioNext(); });
}
